logscale.query:
// Get all process execution and DNS related events on Windows
(#event_simpleName=ProcessRollup2 OR #event_simpleName=DnsRequest) event_platform=Win
// Normalize file name value across both events (pick whichever is populated)
| filename:=coalesce([Filename, ContextBaseFileName])
// Make sure responsible process is a web browser
| in(field="filename", values=["chrome.exe","firefox.exe","msedge.exe"], ignoreCase=true)
// Normalize Falcon PID
| falconPID:=TargetProcessID
| falconPID:=ContextProcessId
// Use join to make sure DNS resolution has the same PID value
| selfJoinFilter(field=[aid, falconPID], where=[{#event_simpleName=ProcessRollup2}, {#event_simpleName=DnsRequest}])
// Aggregate the results
| groupBy([aid, falconPID], function=collect([ComputerName, UserName, filename, DomainName]))

//Query will also ask for parameters, if needed
#event_simpleName=UserLogon
| ComputerName=?ComputerName
| UserName=?UserName
//Enrich with the logontype via falcon helper
| $helper(field=LogonType)
//Lookup only for Interactive logons and unlock events
| LogonType="Interactive" OR LogonType="Unlock" OR LogonType="Cached Interactive"
| LogonType=LogonType
| table([@timestamp, ComputerName, UserName, LogonType],limit=20000)
